// ══════════════════════════════════════════════
//  GUIDES — écrans redessinés (vectoriels) pour la visite animée
//
//  Chaque écran du site est reconstruit en HTML/SVG, avec les données de démonstration.
//  Les éléments expliqués portent data-gd="<id>" : la visite (22-guides.js) cadre la caméra
//  dessus et rejoue leurs animations (courbes qui se tracent, barres qui montent, chiffres
//  qui défilent, lignes qui arrivent). L'état final est l'état par défaut du CSS.
// ══════════════════════════════════════════════

// ───────── Petits outils
const gsF = (n, d = 0) => { const neg = n < 0; let [i, f] = Math.abs(n).toFixed(d).split('.'); i = i.replace(/\B(?=(\d{3})+(?!\d))/g, ' '); return (neg ? '−' : '') + i + (f ? ',' + f : ''); };
const gsE = (n, d = 0, sg) => (sg && n > 0 ? '+' : '') + gsF(n, d) + ' €';
// nombre qui défile (valeur finale écrite d'avance)
const gsN = (v, o = {}) => { const u = o.u == null ? ' €' : o.u, d = o.d || 0; return `<span class="gs-n" data-v="${v}" data-d="${d}" data-s="${o.s ? 1 : 0}" data-u="${u}">${(o.s && v > 0 ? '+' : '') + gsF(v, d) + u}</span>`; };
const gsC = (id, html, o = {}) => `<div class="gs-c ${o.cls || ''}"${id ? ` data-gd="${id}"` : ''} style="${o.st || ''}">${html}</div>`;
const gsR = (items, st) => `<div class="gs-r" style="${st || ''}">${items.join('')}</div>`;
const gsH = (t, c, right) => `<div class="gs-h"${c ? ` style="--hc:${c}"` : ''}>${t}${right ? `<span style="margin-left:auto;display:flex;gap:8px;align-items:center">${right}</span>` : ''}</div>`;
const gsP = (t, c, bd) => `<span class="gs-pill${bd ? ' bd' : ''}" style="color:${c}">${t}</span>`;
const gsB = (t, k, st) => `<span class="gs-btn ${k || ''}" style="${st || ''}">${t}</span>`;
const gsFld = (l, v, o = {}) => `<div class="gs-f"${o.st ? ` style="${o.st}"` : ''}><span class="gs-lab">${l}</span><div class="gs-in${o.sel ? ' sel' : ''}"${o.c ? ` style="color:${o.c}"` : ''}>${v}${o.u ? `<span class="u">${o.u}</span>` : ''}</div>${o.hint ? `<div class="gs-sub" style="margin-top:4px">${o.hint}</div>` : ''}</div>`;
const gsSel = (v, st) => `<div class="gs-in sel" style="${st || ''}">${v}</div>`;
const GS_I = {
  bank: '<path d="M3 21h18"/><path d="M5 21V10M9.5 21V10M14.5 21V10M19 21V10"/><path d="m12 3 9 5H3z"/>',
  plane: '<path d="M17.8 19.2 16 11l3.5-3.5C21 6 21.5 4 21 3c-1-.5-3 0-4.5 1.5L13 8 4.8 6.2c-.5-.1-.9.1-1.1.5l-.3.5c-.2.5-.1 1 .3 1.3L9 12l-2 3H4l-1 1 3 2 2 3 1-1v-3l3-2 3.5 5.3c.3.4.8.5 1.3.3l.5-.2c.4-.3.6-.7.5-1.2z"/>',
  bed: '<path d="M2 20v-8a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v8"/><path d="M4 10V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v4"/><path d="M12 4v6"/><path d="M2 18h20"/>',
  file: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/><path d="M8 13h2M14 13h2M8 17h2M14 17h2"/>',
  cal: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
  wallet: '<path d="M19 7V4a1 1 0 0 0-1-1H5a2 2 0 0 0 0 4h15a1 1 0 0 1 1 1v4h-3a2 2 0 0 0 0 4h3a1 1 0 0 0 1-1v-2a1 1 0 0 0-1-1"/><path d="M3 5v14a2 2 0 0 0 2 2h15a1 1 0 0 0 1-1v-4"/>',
  build: '<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M9 22v-4h6v4M8 6h.01M16 6h.01M12 6h.01M12 10h.01M12 14h.01M16 10h.01M16 14h.01M8 10h.01M8 14h.01"/>',
  trophy: '<path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6M18 9h1.5a2.5 2.5 0 0 0 0-5H18M4 22h16M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22M18 2H6v7a6 6 0 0 0 12 0V2z"/>',
  bell: '<path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>',
  card: '<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/>',
  target: '<circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',
  home: '<path d="M3 10.5 12 3l9 7.5"/><path d="M5 9v11h14V9"/><path d="M10 20v-6h4v6"/>',
  check: '<path d="M20 6 9 17l-5-5"/>',
  pdf: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M9 15h6M9 18h4"/>',
  chart: '<path d="M3 3v18h18"/><path d="M8 17v-5M13 17V7M18 17v-8"/>',
  coins: '<circle cx="8" cy="8" r="6"/><path d="M18.09 10.37A6 6 0 1 1 10.34 18M7 6h1v4M16.71 13.88l.7.71-2.82 2.82"/>',
  key: '<circle cx="7.5" cy="15.5" r="5.5"/><path d="m21 2-9.6 9.6M15.5 7.5l3 3L22 7l-3-3"/>',
  users: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
  gear: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06A1.65 1.65 0 0 0 4.68 15a1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06A1.65 1.65 0 0 0 9 4.68a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06A1.65 1.65 0 0 0 19.4 9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>',
  calc: '<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M8 6h8M8 11h.01M12 11h.01M16 11h.01M8 15h.01M12 15h.01M16 15h.01M8 19h.01M12 19h.01M16 19h.01"/>',
};
const gsIc = (k, c, sz) => `<span class="gs-ic" style="color:${c}${sz ? `;width:${sz}px;height:${sz}px` : ''}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${GS_I[k]}</svg></span>`;
const gsSvgI = (k, c, sz = 14) => `<svg width="${sz}" height="${sz}" viewBox="0 0 24 24" fill="none" stroke="${c}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0">${GS_I[k]}</svg>`;
const GS_MO = ['janv.', 'févr.', 'mars', 'avr.', 'mai', 'juin', 'juil.', 'août', 'sept.', 'oct.', 'nov.', 'déc.'];
const GS_ML = Array.from({ length: 21 }, (_, i) => i % 2 ? null : [i, GS_MO[i % 12], i % 12 === 0 ? String(2025 + i / 12) : '']).filter(Boolean);
let gsUid = 0;

function gsSmooth(p) {
  let d = `M${p[0][0].toFixed(1)},${p[0][1].toFixed(1)}`;
  for (let i = 0; i < p.length - 1; i++) {
    const a = p[i - 1] || p[i], b = p[i], c = p[i + 1], e = p[i + 2] || c;
    d += `C${(b[0] + (c[0] - a[0]) / 6).toFixed(1)},${(b[1] + (c[1] - a[1]) / 6).toFixed(1)} ${(c[0] - (e[0] - b[0]) / 6).toFixed(1)},${(c[1] - (e[1] - b[1]) / 6).toFixed(1)} ${c[0].toFixed(1)},${c[1].toFixed(1)}`;
  }
  return d;
}

// Courbe(s) : o = { w, h, min, max, ticks, tf, xl, n, series: [{ d, c, area, dash, off, end, neg }] }
function gsLine(o) {
  const w = o.w || 1020, h = o.h || 200, pl = o.pl == null ? 40 : o.pl, pr = o.pr == null ? 14 : o.pr, pt = 10, pb = o.xl ? 30 : 8;
  const n = o.n || o.series[0].d.length, X = i => pl + i * (w - pl - pr) / (n - 1);
  const mn = o.min || 0, mx = o.max, Y = v => pt + (mx - v) / (mx - mn) * (h - pt - pb), y0 = Y(Math.max(mn, 0));
  let s = `<svg class="gs-svg" viewBox="0 0 ${w} ${h}" style="height:${h}px"><defs>`, body = '';
  (o.ticks || []).forEach(t => { body += `<line x1="${pl}" x2="${w - pr}" y1="${Y(t)}" y2="${Y(t)}" stroke="rgba(255,255,255,${t === 0 && mn < 0 ? .18 : .06})"/><text x="${pl - 8}" y="${Y(t) + 3}" text-anchor="end">${o.tf ? o.tf(t) : t}</text>`; });
  (o.xl || []).forEach(([i, l, l2]) => { body += `<text x="${X(i)}" y="${h - 16}" text-anchor="middle">${l}</text>${l2 ? `<text x="${X(i)}" y="${h - 4}" text-anchor="middle" style="font-size:9px">${l2}</text>` : ''}`; });
  if (o.band) body += `<rect x="${X(o.band[0])}" y="${pt}" width="${X(o.band[1]) - X(o.band[0])}" height="${h - pt - pb}" fill="rgba(255,255,255,.03)"/><text x="${X(o.band[0]) + 8}" y="${pt + 12}" style="font-size:9px;letter-spacing:.1em">PRÉVISION</text>`;
  o.series.forEach((se, k) => {
    const off = se.off || 0, pts = se.d.map((v, i) => v == null ? null : [X(i + off), Y(v)]).filter(Boolean), d = gsSmooth(pts), id = 'gsg' + (++gsUid), dl = `--dl:${se.dl == null ? k * .45 : se.dl}s`;
    let stroke = se.c;
    if (se.neg) { const zr = (y0 - pt) / (h - pt - pb); s += `<linearGradient id="${id}s" gradientUnits="userSpaceOnUse" x1="0" x2="0" y1="${pt}" y2="${h - pb}"><stop offset="${zr}" stop-color="${se.c}"/><stop offset="${zr}" stop-color="#f0566a"/></linearGradient>`; stroke = `url(#${id}s)`; }
    if (se.area) {
      if (se.neg) { const zr = (y0 - pt) / (h - pt - pb); s += `<linearGradient id="${id}" gradientUnits="userSpaceOnUse" x1="0" x2="0" y1="${pt}" y2="${h - pb}"><stop offset="0" stop-color="${se.c}" stop-opacity=".3"/><stop offset="${zr}" stop-color="${se.c}" stop-opacity=".02"/><stop offset="${zr}" stop-color="#f0566a" stop-opacity=".05"/><stop offset="1" stop-color="#f0566a" stop-opacity=".45"/></linearGradient>`; }
      else s += `<linearGradient id="${id}" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="${se.c}" stop-opacity=".3"/><stop offset="1" stop-color="${se.c}" stop-opacity="0"/></linearGradient>`;
      body += `<path class="gs-wipe" style="${dl}" d="${d}L${pts[pts.length - 1][0]},${y0}L${pts[0][0]},${y0}Z" fill="url(#${id})"/>`;
    }
    if (se.dash) body += `<path class="gs-wipe" style="${dl}" d="${d}" fill="none" stroke="${se.c}" stroke-width="${se.w || 2}" stroke-dasharray="6 5"/>`;
    else body += `<path class="gs-draw" pathLength="1" style="${dl}" d="${d}" fill="none" stroke="${stroke}" stroke-width="${se.w || 2.4}" stroke-linecap="round"/>`;
    if (se.dots) pts.forEach((p, i) => { body += `<circle class="gs-pop" style="--i:${i * .7};--b:calc(var(--b,0s) + .2s)" cx="${p[0]}" cy="${p[1]}" r="3.2" fill="#141922" stroke="${se.c}" stroke-width="1.8"/>`; });
    if (se.end) { const p = pts[pts.length - 1]; body += `<g class="gs-pop" style="--i:16"><circle cx="${p[0]}" cy="${p[1]}" r="4.5" fill="${se.c}"/><rect x="${p[0] - 66}" y="${p[1] - 30}" width="60" height="20" rx="10" fill="#0b0d12" stroke="${se.c}"/><text x="${p[0] - 36}" y="${p[1] - 16.5}" text-anchor="middle" style="fill:${se.c};font-weight:800">${se.end}</text></g>`; }
  });
  return s + '</defs>' + body + '</svg>';
}

// Barres : o = { w, h, min, max, ticks, tf, xl, data: [[v1, v2…]…], cols, group }
function gsBars(o) {
  const w = o.w || 1020, h = o.h || 200, pl = o.pl == null ? 40 : o.pl, pr = 10, pt = 8, pb = o.xl ? 30 : 8;
  const n = o.data.length, mn = o.min || 0, mx = o.max, Y = v => pt + (mx - v) / (mx - mn) * (h - pt - pb), y0 = Y(0);
  const slot = (w - pl - pr) / n, bw = o.bw || slot * .62;
  let s = `<svg class="gs-svg" viewBox="0 0 ${w} ${h}" style="height:${h}px">`;
  (o.ticks || []).forEach(t => { s += `<line x1="${pl}" x2="${w - pr}" y1="${Y(t)}" y2="${Y(t)}" stroke="rgba(255,255,255,${t === 0 ? .14 : .06})"/><text x="${pl - 8}" y="${Y(t) + 3}" text-anchor="end">${o.tf ? o.tf(t) : t}</text>`; });
  (o.xl || []).forEach(([i, l, l2]) => { const x = pl + slot * (i + .5); s += `<text x="${x}" y="${h - 16}" text-anchor="middle">${l}</text>${l2 ? `<text x="${x}" y="${h - 4}" text-anchor="middle" style="font-size:9px">${l2}</text>` : ''}`; });
  o.data.forEach((vals, i) => {
    let up = 0, dn = 0;
    const gw = o.group ? bw / vals.length : bw;
    vals.forEach((v, j) => {
      if (v == null || v === 0) return;
      const x = pl + slot * i + (slot - bw) / 2 + (o.group ? j * gw : 0), c = o.cols[j], rx = Math.min(3, gw / 4);
      let ya, yb;
      if (o.group) { ya = Y(Math.max(v, 0)); yb = Y(Math.min(v, 0)); }
      else if (v > 0) { ya = Y(up + v); yb = Y(up); up += v; } else { ya = Y(dn); yb = Y(dn + v); dn += v; }
      s += `<rect class="gs-grow${v < 0 ? ' dn' : ''}" style="--i:${i + j * .5}" x="${x.toFixed(1)}" y="${ya.toFixed(1)}" width="${(gw - (o.group ? 2 : 0)).toFixed(1)}" height="${Math.max(1, yb - ya).toFixed(1)}" rx="${rx}" fill="${c}"/>`;
    });
  });
  if (o.line) { const X = i => pl + slot * (i + .5), pts = o.line.d.map((v, i) => [X(i), Y(v)]); s += `<path class="gs-draw" pathLength="1" style="--dl:.6s" d="${gsSmooth(pts)}" fill="none" stroke="${o.line.c}" stroke-width="2.2"/>` + pts.map((p, i) => `<circle class="gs-pop" style="--i:${i * .5 + 4}" cx="${p[0]}" cy="${p[1]}" r="2.8" fill="#141922" stroke="${o.line.c}" stroke-width="1.6"/>`).join(''); }
  return s + '</svg>';
}

// Anneau : segs = [[valeur, couleur]…]
function gsDonut(segs, size, center) {
  const tot = segs.reduce((a, s) => a + s[0], 0), sw = size * .15, r = size / 2 - sw / 2;
  let a = 0, s = `<div style="position:relative;width:${size}px;height:${size}px;margin:0 auto"><svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">`;
  segs.forEach(([v, c], i) => { const f = v / tot; s += `<circle class="gs-seg" style="--i:${i}" cx="${size / 2}" cy="${size / 2}" r="${r}" fill="none" stroke="${c}" stroke-width="${sw}" pathLength="1" stroke-dasharray="${Math.max(.001, f - .008)} 1" transform="rotate(${-90 + a * 360} ${size / 2} ${size / 2})"/>`; a += f; });
  return s + `</svg><div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center">${center || ''}</div></div>`;
}
const gsLegRows = rows => rows.map((r, i) => `<div class="gs-tr" style="--i:${i + 6};display:flex;align-items:center;gap:8px;padding:5px 0;font-size:12px"><span class="gs-dot" style="background:${r[1]}"></span><span style="flex:1">${r[0]}</span>${r[2] ? `<b class="${r[3] || 'g'}" style="font-weight:700">${r[2]}</b>` : ''}${r[4] ? `<span class="gs-sub" style="width:44px;text-align:right">${r[4]}</span>` : ''}</div>`).join('');

// Tableau : cols = [[titre, 'r'?]…] ; rows = [[cellules…] | { c: [...], cls }]
function gsTable(cols, rows, o = {}) {
  return `<table class="gs-t"${o.st ? ` style="${o.st}"` : ''}><thead><tr>${cols.map(c => `<th class="${c[1] || ''}"${c[2] ? ` style="width:${c[2]}"` : ''}>${c[0]}</th>`).join('')}</tr></thead><tbody>${rows.map((r, i) => { const c = r.c || r; return `<tr class="gs-tr ${r.cls || ''}" style="--i:${i}">${c.map((v, j) => `<td class="${cols[j] && cols[j][1] || ''}">${v}</td>`).join('')}</tr>`; }).join('')}</tbody></table>`;
}
// Barres horizontales (drivers, paliers) : rows = [[libellé, sous-libellé, valeur texte, fraction -1..1, couleur]]
function gsDrivers(rows, o = {}) {
  return rows.map((r, i) => { const f = Math.abs(r[3]), neg = r[3] < 0; return `<div class="gs-tr" style="--i:${i};display:flex;align-items:center;gap:12px;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.04)"><div style="width:190px;flex-shrink:0"><div style="font-weight:700;font-size:12px">${r[0]}</div>${r[1] ? `<div class="gs-sub" style="font-size:10.5px">${r[1]}</div>` : ''}</div><div style="flex:1;position:relative;height:16px">${o.mid ? `<div style="position:absolute;left:50%;top:-6px;bottom:-6px;border-left:1px solid rgba(255,255,255,.15)"></div>` : ''}<i class="gs-hgrow${neg && o.mid ? ' rt' : ''}" style="--i:${i};position:absolute;top:2px;height:12px;border-radius:4px;background:${r[4]};${o.mid ? (neg ? `right:50%;width:${f * 50}%` : `left:50%;width:${f * 50}%`) : `left:${(r[5] || 0) * 100}%;width:${f * 100}%`}"></i></div><b style="width:78px;text-align:right;color:${r[4]};font-size:12px">${r[2]}</b></div>`; }).join('');
}
function gsSpark(d, c, w = 96, h = 30) {
  const mn = Math.min(...d), mx = Math.max(...d), p = d.map((v, i) => [i * w / (d.length - 1), h - 3 - (v - mn) / ((mx - mn) || 1) * (h - 6)]);
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="position:absolute;right:14px;top:12px;overflow:visible"><path class="gs-draw" pathLength="1" style="--dl:.3s" d="${gsSmooth(p)}" fill="none" stroke="${c}" stroke-width="1.8"/><circle class="gs-pop" style="--i:12" cx="${p[p.length - 1][0]}" cy="${p[p.length - 1][1]}" r="2.6" fill="${c}"/></svg>`;
}
const gsCmp = (a, b, ga, gb) => `<div style="margin-top:9px;padding-top:8px;border-top:1px solid rgba(255,255,255,.06);display:grid;grid-template-columns:auto 1fr;gap:4px 10px;align-items:center;font-size:11px;font-weight:600"><span class="gs-sub" style="font-weight:600">vs M-1</span>${gsP(a, ga ? '#22c97a' : '#f0566a')}<span class="gs-sub" style="font-weight:600">vs N-1</span>${gsP(b, gb ? '#22c97a' : '#f0566a')}</div>`;
function gsKpi(lab, val, o = {}) {
  return `${o.ic ? `<div class="gs-lab" style="display:flex;gap:7px;align-items:center">${gsSvgI(o.ic, '#8a9ab2', 13)}${lab}</div>` : `<div class="gs-lab">${lab}</div>`}<div class="gs-big" style="margin-top:7px;color:${o.c || '#e2e8f3'}">${val}</div>${o.sub ? `<div class="gs-sub" style="margin-top:3px">${o.sub}</div>` : ''}${o.spark ? gsSpark(o.spark, o.c) : ''}${o.cmp || ''}${o.icon ? `<div style="position:absolute;right:14px;top:14px;opacity:.75">${gsIc(o.icon, o.ic2 || '#8a9ab2', 44)}</div>` : ''}`;
}
const gsDayTop = (title, right, step) => `<div class="gs-top"><span class="lg">ARTEM<i>IS</i></span><span class="md">- ${title}</span><span class="sp"></span>${step != null ? gsSteps(step) : (right || '')}</div>`;
function gsSteps(k) { return `<div class="gs-steps">${['Import', 'Mapping', 'Validation', 'Base'].map((n, i) => `<span class="gs-step${i === k ? ' on' : i < k ? ' ok' : ''}"><b>${i < k ? '✓' : i + 1}</b>${n}</span>`).join('<hr>')}<hr><span class="gs-step" style="color:#9b6ef3"><b>5</b>Dashboard</span></div>`; }
const gsDashTabs = (on, chip) => `<div class="gs-tabs">${['Synthèse', 'Résultat', 'KPIs', 'Plateformes', 'Budget'].map(n => `<span class="${n === on ? 'on' : ''}">${n}</span>${n === on && chip ? chip.map(c => `<span class="ch${c[1] ? ' on' : ''}">${c[0]}</span>`).join('') : ''}`).join('')}<span style="flex:1"></span>${gsB('Excel', '', 'height:26px')}</div>`;
const gsFilters = (extra) => `<div class="gs-grid" style="grid-template-columns:repeat(${extra ? 4 : 5},auto) 1fr;align-items:end">${[['Société', 'Toutes'], ['Bien', 'Tous'], ['Période', '03/01/2025 → 28/09/2026']].concat(extra ? [['Année', 'Toutes années']] : [['Catégorie', 'Toutes'], ['Driver', '3 mois']]).map(f => gsFld(f[0], f[1], { sel: 1 })).join('')}</div>`;

