    gsC('loan', gsH('Tableau d\'emprunt', '', '<span class="gs-sub" style="text-transform:none;letter-spacing:0">Coût total du crédit : 26 690 €</span>') + gsTable([['Année'], ['Mensualité', 'r'], ['Capital remboursé', 'r'], ['Intérêts', 'r'], ['Assurance', 'r'], ['Capital restant dû', 'r']],
      [[1, '8 605', '6 213', '2 034', '365', '139 887'], [2, '8 605', '6 304', '1 943', '365', '133 583'], [3, '8 605', '6 395', '1 851', '365', '127 188'], [4, '8 605', '6 488', '1 758', '365', '120 700'], [5, '8 605', '6 582', '1 664', '365', '114 118'], [6, '8 605', '6 677', '1 568', '365', '107 441']].map(r => r.map(String)).concat([{ c: ['…', '', '', '', '', ''], cls: '' }, ['20', '8 605', '8 151', '95', '365', '0']])));
