const gsBudTop = () => `<div class="gs-top"><span class="cy" style="font-size:12px;font-weight:700">← Retour</span><span class="lg">ARTEM<i>IS</i></span><span class="md" style="color:#22d3c8;letter-spacing:0">Budget</span><span class="sp"></span>${gsB('Exporter', 'sm')}${gsB('Importer', 'sm')}</div>`;
const gsBudHead = (tab) => `<div class="gs-c flat" data-gd="version" style="margin-bottom:10px"><div style="display:flex;align-items:center;gap:10px">${gsSel('<b style="font-size:14px">2026 · Budget 2026 (référence)</b>', 'height:36px;width:270px')}${gsP('✓ Comparée au réel dans le dashboard', '#22c97a')}<span style="flex:1"></span>${['+ Nouveau', 'Dupliquer', 'Renommer', 'Repartir du réel', 'Supprimer'].map(b => gsB(b, 'sm')).join('')}</div><div style="display:flex;align-items:center;gap:10px;margin-top:8px"><span class="gs-sub" style="font-weight:700">Réel de référence</span>${gsSel('Réel 2025', 'width:200px;height:26px')}<span class="gs-sub">janv. – déc. 2025</span></div></div>` +
  `<div class="gs-tabs gs-c flat" data-gd="tabs" style="margin:0 0 14px">${['Montants par bien', 'Objectifs courte durée', "Vue d'ensemble"].map(t => `<span class="${t === tab ? 'on' : ''}">${t}</span>`).join('')}</div>`;
const GS_BLINE = (t, r, pct, vals, o = {}) => `<tr class="gs-tr ${o.cls || ''}" style="--i:${o.i || 0}"><td>${t}</td><td class="r gs-mut">${r}</td><td class="r" style="color:#f5b731">${pct}</td>${vals.map(v => `<td class="r${o.c ? ' ' + o.c(v) : ''}">${v}</td>`).join('')}</tr>`;
